import assert from 'node:assert/strict';
import { test } from 'node:test';
import {
  EXAMPLE,
  exampleBlock,
  exampleOutputs,
  unitCostRows,
  unitCostsBlock,
} from './docs-capacity.mjs';

const WHERE = {
  commit: 'e3a4e937aa',
  cpu: 'AMD EPYC 7763 64-Core Processor',
  jdk: '25.0.5+8',
};

const round = (store, scenario, name, extra) => ({
  id: `unit.${store}.${scenario.toLowerCase()}-x.100k.${name}`,
  kind: 'unit',
  store,
  scenario,
  keys: 'uniform',
  accounts: 100000,
  ...WHERE,
  ...extra,
});

const pgE1 = [
  round('postgres', 'E1', 'r1-head', {
    rate: 1000,
    value: 1.2,
    nodeCpuMsPerOp: 0.5,
    storeCpuMsPerOp: 0.4,
    busCpuMsPerOp: 0.3,
    commitsPerOp: 0.6,
    walBytesPerOp: 1000,
  }),
  round('postgres', 'E1', 'r2-head', {
    rate: 1000,
    value: 1.4,
    nodeCpuMsPerOp: 0.7,
    storeCpuMsPerOp: 0.4,
    busCpuMsPerOp: 0.3,
    commitsPerOp: 0.8,
    walBytesPerOp: 1200,
  }),
  round('postgres', 'E1', 'r3-head', {
    rate: 1000,
    value: 1.3,
    nodeCpuMsPerOp: 0.6,
    storeCpuMsPerOp: 0.4,
    busCpuMsPerOp: 0.3,
    commitsPerOp: 0.7,
    walBytesPerOp: 1100,
  }),
  round('postgres', 'E1', 'e1-head', {
    rate: 900,
    value: 9,
    nodeCpuMsPerOp: 9,
  }),
];
const pgE3 = [
  round('postgres', 'E3', 'r1-head', {
    rate: 400,
    value: 4,
    nodeCpuMsPerOp: 2,
    storeCpuMsPerOp: 1.5,
    busCpuMsPerOp: 0.5,
    commitsPerOp: 2,
    walBytesPerOp: 4000,
  }),
];
const sustainable = (store, scenario, value) => ({
  id: `sustainable.${store}.${scenario}`,
  kind: 'sustainable',
  store,
  scenario,
  keys: 'uniform',
  value,
  cpuMsPerOp: 1.1,
  ...WHERE,
});
const SNAPSHOT = {
  report: 'actions-snapshot',
  figures: [
    ...pgE1,
    ...pgE3,
    round('mongo', 'E1', 'r1-head', {
      rate: 1500,
      value: 1,
      nodeCpuMsPerOp: 0.3,
      storeCpuMsPerOp: 0.5,
      busCpuMsPerOp: 0.2,
    }),
    round('postgres', 'E1', 'r1-head', { accounts: 1000, rate: 1, value: 99 }),
    sustainable('postgres', 'E1', 2000),
    sustainable('postgres', 'E3', 800),
  ],
};
const AXON = {
  report: 'actions-axon',
  figures: [
    {
      id: 'footprint.axon-pg.100k.wow',
      kind: 'footprint',
      arm: 'wow',
      store: 'postgres',
      bytesPerEvent: [600, 620],
      bytesPerSnapshot: [400, 410],
      ...WHERE,
    },
    {
      id: 'footprint.axon-pg-contention.100k.wow',
      kind: 'footprint',
      arm: 'wow',
      store: 'postgres',
      bytesPerEvent: [700, 700],
      bytesPerSnapshot: [500, 500],
      ...WHERE,
    },
    {
      id: 'footprint.axon-pg.100k.axon',
      kind: 'footprint',
      arm: 'axon',
      store: 'postgres',
      bytesPerEvent: [900, 900],
      bytesPerSnapshot: [900, 900],
      ...WHERE,
    },
  ],
};

test("a unit cost is the median of beta.6's rounds r1 to r3 at 100k accounts, at the rate they ran at", () => {
  const rows = unitCostRows(SNAPSHOT);
  const e1 = rows.find(
    r => r.key === 'E1|uniform' && r.store === 'postgres' && r.at === 'rounds',
  );
  assert.deepEqual(
    [e1.rate, e1.node, e1.database, e1.bus, e1.total, e1.commits, e1.wal],
    [1000, 0.6, 0.4, 0.3, 1.3, 0.7, 1100],
    'an equal-rate round (e1) and a 1k suite are left out',
  );
  assert.equal(rows.filter(r => r.at === 'rounds').length, 3);
  assert.deepEqual(
    rows.map(r => `${r.store} ${r.key} ${r.at}`),
    [
      'postgres E1|uniform rounds',
      'postgres E1|uniform sustainable',
      'postgres E3|uniform rounds',
      'postgres E3|uniform sustainable',
      'mongo E1|uniform rounds',
    ],
    'PostgreSQL first, then by workload and rate',
  );
});

test('T1 names each row its runner, JDK and build, and says what was not measured or not split, in each locale', () => {
  const en = unitCostsBlock('en', [SNAPSHOT]);
  assert.match(en, /^<!-- Generated by \.github\/scripts\/docs-capacity\.mjs/);
  assert.ok(
    en.includes(
      "CPU in ms per command. Build `e3a4e937aa`, JDK 25.0.5+8; each row names its runner's CPU.",
    ),
  );
  assert.ok(
    en.includes(
      '| E1 write | PostgreSQL | 1,000/s | 0.6 | 0.4 | 0.3 | 1.3 | 0.7 | 1,100 | EPYC 7763 |',
    ),
  );
  assert.ok(
    en.includes(
      '| E1 write | PostgreSQL | 2,000/s, sustainable | not split | not split | not split | 1.1 | not split | not split |',
    ),
  );
  assert.ok(
    en.includes(
      '| E1 write | MongoDB | 1,500/s | 0.3 | 0.5 | 0.2 | 1 | not measured | not measured |',
    ),
  );
  const zh = unitCostsBlock('zh', [SNAPSHOT]);
  assert.ok(zh.includes('| E1 写入 | PostgreSQL | 1,000/s | 0.6 |'));
  assert.ok(zh.includes('| 未测 | 未测 | EPYC 7763 |'));
  assert.throws(
    () => unitCostsBlock('en', []),
    /the capacity blocks need the actions-snapshot headline/,
  );
});

test("the worked example's outputs are the formulas over the rows it names", () => {
  const out = exampleOutputs([SNAPSHOT, AXON]);
  // 2,000/s of E1 at a sustainable 2,000/s and 500/s of E3 at 800/s: 1.625 nodes' worth.
  assert.equal(out.nodesByRate, 2000 / 2000 + 500 / 800);
  assert.equal(out.nodes, Math.ceil(1.625 / EXAMPLE.share) + 1);
  assert.equal(out.nodeCores, (2000 * 0.6 + 500 * 2) / 1000);
  assert.equal(out.databaseCores, (2000 * 0.4 + 500 * 1.5) / 1000);
  assert.equal(out.commits, 2000 * 0.7 + 500 * 2);
  assert.equal(out.walBytes, 2000 * 1100 + 500 * 4000);
  assert.equal(
    out.perEvent,
    620,
    "the named suite's larger session, not another suite's or Axon's",
  );
  assert.equal(out.storageBytes, 1_000_000 * 620 * 365 * 3);
  assert.equal(out.snapshotBytes, 2_000_000 * 410);
  assert.throws(
    () => exampleOutputs([{ ...SNAPSHOT, figures: pgE1 }, AXON]),
    /needs a sustainable row for E1\|uniform/,
  );
});

test('the worked example prints each output with the rows it read, in each locale', () => {
  const en = exampleBlock('en', [SNAPSHOT, AXON]);
  assert.ok(
    en.includes(
      "| Nodes, by sustainable rate | 163% of one node's sustainable rate: 3 at 60% each, and one more for a lost node's partitions, 4 |",
    ),
  );
  assert.ok(
    en.includes(
      'T1: E1 write, PostgreSQL, 1,000/s, EPYC 7763, `e3a4e937aa`; T1: E3 saga step, PostgreSQL, 400/s, EPYC 7763, `e3a4e937aa`',
    ),
  );
  assert.ok(
    en.includes(
      '| Log storage a year | 226.3 GB | 620 B per event, the actions-axon report, Wow on PostgreSQL, EPYC 7763, `e3a4e937aa` |',
    ),
  );
  const zh = exampleBlock('zh', [SNAPSHOT, AXON]);
  assert.ok(
    zh.includes(
      '| 每秒提交数 | 每秒 2,400 | T1：E1 写入，PostgreSQL，1,000/s，EPYC 7763，`e3a4e937aa`；T1：E3 Saga 一步',
    ),
  );
});
